"""The code generated by XenonRecomp no longer adds `base` to a guest address
by hand: every access goes through PPC_HOST (patch 0003), which in runtime/ppc_detail.h
applies the offset of the 0xE0000000 view. Skipped without generated code."""
import re
from pathlib import Path

import pytest

REPO = Path(__file__).resolve().parents[1]
GENERATED = REPO / "build" / "generated"

# Allowed: lookups in the function table (code addresses 0x82...,
# below the 0xE view, no offset).
ALLOWED = ("PPC_LOOKUP_FUNC",)
# `base +` with any whitespace (also `base+`), only as a whole word.
BASE_PLUS = re.compile(r"\bbase\s*\+")


def test_generated_code_has_no_direct_base_access():
    if not (GENERATED / "ppc_recomp.0.cpp").exists():
        pytest.skip("generated code missing (build/generated/ppc_recomp.0.cpp)")
    offenders = []
    for path in sorted(GENERATED.glob("ppc_recomp.*.cpp")):
        with path.open(encoding="utf-8", errors="replace") as f:
            for number, line in enumerate(f, 1):
                if BASE_PLUS.search(line) and not any(token in line for token in ALLOWED):
                    offenders.append(f"{path.name}:{number}: {line.strip()}")
    assert offenders[:20] == [], f"{len(offenders)} `base +` accesses outside PPC_HOST"


def test_generated_code_reads_timebase_through_macro():
    """mftb goes through PPC_QUERY_TIMEBASE (patch 0004), which the runtime redefines
    at 50 MHz: no `__rdtsc` (the PC's TSC, GHz) in the generated code."""
    if not (GENERATED / "ppc_recomp.0.cpp").exists():
        pytest.skip("generated code missing (build/generated/ppc_recomp.0.cpp)")
    offenders = []
    macro_sites = 0
    for path in sorted(GENERATED.glob("ppc_recomp.*.cpp")):
        with path.open(encoding="utf-8", errors="replace") as f:
            for number, line in enumerate(f, 1):
                if "__rdtsc" in line:
                    offenders.append(f"{path.name}:{number}: {line.strip()}")
                if "PPC_QUERY_TIMEBASE()" in line:
                    macro_sites += 1
    assert offenders[:20] == [], f"{len(offenders)} `__rdtsc` reads in the generated code"
    assert macro_sites > 0, "no mftb translated with PPC_QUERY_TIMEBASE()"


def test_no_function_falls_off_after_conditional_return():
    """No generated function ends with a conditional return (`beqlr`,
    `bdzlr`, ...): after `if (...) return;` execution would fall out of the
    function instead of continuing (CRT memset, patch 0005)."""
    if not (GENERATED / "ppc_recomp.0.cpp").exists():
        pytest.skip("generated code missing (build/generated/ppc_recomp.0.cpp)")
    impl = re.compile(r"PPC_FUNC_IMPL\(__imp__(sub_[0-9A-F]+)\)")
    comment = re.compile(r"\t// (\S+)")
    conditional_return = re.compile(r"^b.*lr[+-]?$")
    offenders = []
    for path in sorted(GENERATED.glob("ppc_recomp.*.cpp")):
        func = last_op = None
        with path.open(encoding="utf-8", errors="replace") as f:
            for line in f:
                line = line.rstrip("\n")
                if m := impl.match(line):
                    func, last_op = m.group(1), None
                elif m := comment.match(line):
                    last_op = m.group(1)
                elif line == "}" and func:
                    if last_op and conditional_return.match(last_op) and last_op not in ("blr", "blrl"):
                        offenders.append(f"{func}: {last_op}")
                    func = None
    assert offenders[:20] == [], f"{len(offenders)} functions fall out after a conditional return"
